class ConfigService {
  private constructor() {}
  get(key: string) { return process.env[key]; }
}
const config = new ConfigService();
export default config;

// Version B
export class ConfigService {
  constructor(private data: Record<string,string>) {}
  get(key: string) { return this.data[key]; }
}
export function createConfig(data: Record<string,string>) { return new ConfigService(data); }
